from yait_aichain.state import FileStore, SuspendedResult
from yait_aichain.tools import Wait, Tool


class SendText(Tool):
    name = "send_text"
    description = "Send the approved text."
    parameters = {
        "type": "object",
        "properties": {
            "text": {"type": "string"}
        },
        "required": ["text"],
    }

    def run(self, text, options=None):
        return f"SENT: {text}"


draft_reply = Skill(
    Model("gpt-5.4-mini"),
    prompt=(
        "Draft a concise, polite reply to this message:\n"
        "{message}\n\n"
        "Return only the reply text."
    ),
)

chain = Chain(
    steps=[
        (draft_reply, "draft"),
        Wait(reason="Human approval required"),
        (SendText(), "sent", {"text": "approved_text"}),
    ],
    store=FileStore("runs"),
)

message = "Can you please confirm tomorrow's meeting time?"
result = chain.run(variables={"message": message})

if isinstance(result, SuspendedResult):
    approved_text = f"APPROVED: {result.variables['draft']}"
    resumed = chain.resume(result.run_id, signal={"approved_text": approved_text})
    print(resumed["sent"])
else:
    print(result["sent"])

