from yait_aichain.agent import step_count


class Calculator(Tool):
    name = "calculator"
    description = "Evaluate a simple arithmetic expression."
    parameters = {
        "type": "object",
        "properties": {
            "input": {"type": "string", "description": "Arithmetic expression to evaluate"}
        },
        "required": ["input"],
    }

    def run(self, input, options=None):
        allowed = set("0123456789+-*/(). ")
        if any(ch not in allowed for ch in input):
            raise ValueError("Only simple arithmetic expressions are allowed.")
        return eval(input, {"__builtins__": {}}, {})


def main():
    agent = Agent(
        Model("gpt-5.4-mini"),
        tools=[Calculator()],
        instructions="Use the calculator tool for arithmetic. Be concise and exact.",
        stop_when=[step_count(6)],
    )

    result = agent.run("What is 17 * 23?")
    print(result.output)
    print(result.stopped_by)


if __name__ == "__main__":
    main()

