class SearchLikeTool(Tool):
    name = "search_like_tool"
    description = "A simple search-like tool that returns a few relevant facts for a question."
    parameters = {
        "type": "object",
        "properties": {
            "input": {"type": "string"}
        },
        "required": ["input"],
    }

    def run(self, input, options=None):
        q = input.lower()
        facts = []

        if "python" in q and "generator" in q:
            facts.append("Python generators produce values lazily using yield.")
            facts.append("They can save memory by not building the whole sequence at once.")
        if "space" in q or "mars" in q:
            facts.append("Mars is the fourth planet from the Sun.")
            facts.append("A Mars day is called a sol and is slightly longer than an Earth day.")
        if "ocean" in q or "deep sea" in q:
            facts.append("The deep ocean contains extreme pressure, darkness, and cold temperatures.")
            facts.append("Some organisms there produce light through bioluminescence.")
        if not facts:
            facts.append("No direct facts found; try broader keywords or related concepts.")
            facts.append("A good next step is to reformulate the question into smaller subquestions.")

        return "\n".join(facts)


agent = Agent(
    Model("gpt-5.4-mini"),
    tools=[SearchLikeTool()],
    instructions=(
        "You are a research agent. Use the search-like tool to gather facts.\n"
        "If you stop making progress for three steps, change approach.\n"
        "Do not exceed ten steps.\n"
        "Be concise and answer the question with evidence from the tool."
    ),
    stop_when=[step_count(10), stalled(3)],
)

question = "What are two important facts about Mars?"
result = agent.run(question)

print(result.output)

