class KnowledgeTool(Tool):
    name = "knowledge_lookup"
    description = "Provide a concise factual answer to a research question."
    parameters = {
        "type": "object",
        "properties": {
            "input": {"type": "string"},
        },
        "required": ["input"],
    }

    def run(self, input, options=None):
        q = input.lower()

        facts = {
            "why is the sky blue": "The sky appears blue because air molecules scatter shorter blue wavelengths of sunlight more than longer red wavelengths.",
            "what causes tides": "Tides are caused mainly by the gravitational pull of the Moon, with the Sun also contributing.",
            "how do solar panels work": "Solar panels convert sunlight into electricity using the photovoltaic effect in semiconductor cells.",
            "what is photosynthesis": "Photosynthesis is the process by which plants use sunlight to turn carbon dioxide and water into glucose and oxygen.",
        }

        for key, answer in facts.items():
            if key in q:
                return answer

        return (
            "I do not have a direct stored fact for that question, but "
            "it is a question about the topic and should be answered by reasoning from reliable sources."
        )


question_skill = Skill(
    Model("gpt-5.4-mini"),
    prompt=(
        "Turn the topic '{topic}' into one clear, focused research question. "
        "Return only the question."
    ),
)

agent = Agent(
    Model("gpt-5.4-mini"),
    tools=[KnowledgeTool()],
    instructions=(
        "Answer the research question as directly and concisely as possible. "
        "Use the knowledge_lookup tool if helpful."
    ),
    stop_when=[step_count(6)],
)

pipeline = Chain(steps=[(question_skill, "task"), (agent, "answer")])

result = pipeline.run(variables={"topic": "why the sky is blue"})

print(result["answer"])

