from yait_aichain.tools import Tool


class SearchTool(Tool):
    name = "search"
    description = "Search the web-like knowledge base for relevant information."
    parameters = {
        "type": "object",
        "properties": {
            "query": {"type": "string"}
        },
        "required": ["query"],
    }

    def run(self, query, options=None):
        q = query.lower()
        kb = [
            {
                "title": "Solar energy",
                "text": "Solar panels convert sunlight into electricity using photovoltaic cells."
            },
            {
                "title": "Wind energy",
                "text": "Wind turbines convert kinetic energy from wind into electrical power."
            },
            {
                "title": "Photosynthesis",
                "text": "Plants convert light energy into chemical energy through photosynthesis."
            },
            {
                "title": "Batteries",
                "text": "Batteries store electrical energy and can release it later for use."
            },
        ]
        results = []
        for item in kb:
            score = 0
            hay = f'{item["title"]} {item["text"]}'.lower()
            for token in q.split():
                if token in hay:
                    score += 1
            if score > 0:
                results.append(f'{item["title"]}: {item["text"]}')
        if not results:
            results.append("No direct match found. Try a broader or related query.")
        return "\n".join(results)


agent = Agent(
    Model("gpt-5.4-mini"),
    tools=[SearchTool()],
    instructions=(
        "You are a research agent. Use the search tool to gather facts.\n"
        "If you stop making progress for three steps, change your approach.\n"
        "Be concise and answer the question with supported facts."
    ),
    stop_when=[step_count(10), stalled(3)],
)

result = agent.run("What is solar energy and how does it compare to wind energy?")
print(result.output)

