class SearchTool(Tool):
    name = "search"
    description = "Search a small built-in knowledge base for relevant snippets."
    parameters = {
        "type": "object",
        "properties": {
            "query": {"type": "string"}
        },
        "required": ["query"]
    }

    def run(self, query, options=None):
        kb = [
            {
                "title": "Solar energy",
                "text": "Solar panels convert sunlight into electricity. Efficiency depends on panel type, angle, shading, and temperature."
            },
            {
                "title": "Wind energy",
                "text": "Wind turbines generate electricity from moving air. Output varies with wind speed and turbine design."
            },
            {
                "title": "Battery storage",
                "text": "Battery storage helps balance renewable energy by storing excess electricity for later use."
            },
            {
                "title": "Research strategy",
                "text": "When progress stalls, change approach: narrow the question, search for definitions, compare sources, or test an alternative angle."
            },
        ]

        q = query.lower()
        scored = []
        for item in kb:
            score = sum(1 for term in q.split() if term in (item["title"] + " " + item["text"]).lower())
            if score > 0:
                scored.append((score, item))
        scored.sort(key=lambda x: x[0], reverse=True)

        if not scored:
            return "No direct match found. Try a narrower or related query."

        return "\n\n".join(f"{item['title']}: {item['text']}" for _, item in scored[:3])

agent = Agent(
    Model("gpt-5.4-mini"),
    tools=[SearchTool()],
    instructions=(
        "You are a research agent. Use the search tool to gather evidence, "
        "synthesize a concise answer, and cite the relevant points from the tool output. "
        "If you stop making progress for three steps, change approach."
    ),
    stop_when=[step_count(10), stalled(3)],
)

result = agent.run("What are the main factors that affect solar panel efficiency?")
print(result.output)

