class SimpleLookup(Tool):
    name = "simple_lookup"
    description = "Return a short factual answer for a small set of common research topics."
    parameters = {
        "type": "object",
        "properties": {
            "query": {"type": "string"}
        },
        "required": ["query"]
    }

    def run(self, query, options=None):
        q = query.lower().strip()

        if "solar" in q and "cost" in q:
            return "Solar costs have fallen dramatically over the last decade due to cheaper panels, better manufacturing, and scale."
        if "ai" in q and "productivity" in q:
            return "AI can boost productivity by automating routine tasks and speeding up analysis, though results depend on workflow and adoption."
        if "climate" in q and "impact" in q:
            return "Climate impacts include more frequent heatwaves, heavier rainfall, sea-level rise, and increased ecosystem stress."
        if "biodiversity" in q:
            return "Biodiversity is important because it supports ecosystem stability, resilience, food systems, and services like pollination."
        return f"I do not have a specific lookup for: {query}"


topic = "How is artificial intelligence affecting workplace productivity?"

question_skill = Skill(
    Model("gpt-5.4-mini"),
    prompt="Turn this topic into one clear, focused research question: {topic}",
)

agent = Agent(
    Model("gpt-5.4-mini"),
    tools=[SimpleLookup()],
    instructions=(
        "Answer the research question using the tool when helpful. "
        "Be concise and directly answer the question."
    ),
    stop_when=[step_count(8)],
)

pipeline = Chain(steps=[(question_skill, "task"), (agent, "answer")])

result = pipeline.run(variables={"topic": topic})
print(result["answer"])

