from yait_aichain.tools import Wait, Tool


class SendText(Tool):
    name = "send_text"
    description = "Send the approved text."
    parameters = {
        "type": "object",
        "properties": {
            "text": {"type": "string"}
        },
        "required": ["text"],
    }

    def run(self, text, options=None):
        print(text)
        return {"sent": text}


draft_reply = Skill(
    Model("gpt-5.4-mini"),
    prompt="Draft a polite reply to this message:\n\n{message}",
)

send_text = SendText()

chain = Chain(
    steps=[
        (draft_reply, "draft"),
        Wait(reason="Human approval required"),
        (send_text, "sent", {"text": "approved_text"}),
    ],
    store=FileStore("runs"),
)

initial = chain.run(variables={"message": "Could you please confirm the meeting for tomorrow at 3 PM?"})

if isinstance(initial, SuspendedResult):
    approved_text = (
        initial.variables["draft"]
        if hasattr(initial, "variables") and "draft" in initial.variables
        else "Approved reply: Confirmed for tomorrow at 3 PM."
    )
    resumed = chain.resume(initial.run_id, signal={"approved_text": approved_text})
    if isinstance(resumed, dict):
        print(resumed.get("sent"))
    else:
        print(resumed)
else:
    print(initial)

