import ast
import operator as op


class Calculator(Tool):
    name = "calculator"
    description = "Evaluate a simple arithmetic expression safely."
    parameters = {
        "type": "object",
        "properties": {
            "expression": {"type": "string"}
        },
        "required": ["expression"]
    }

    def run(self, expression, options=None):
        allowed_ops = {
            ast.Add: op.add,
            ast.Sub: op.sub,
            ast.Mult: op.mul,
            ast.Div: op.truediv,
            ast.FloorDiv: op.floordiv,
            ast.Mod: op.mod,
            ast.Pow: op.pow,
            ast.USub: op.neg,
            ast.UAdd: op.pos,
        }

        def eval_node(node):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
                return node.value
            if isinstance(node, ast.BinOp):
                left = eval_node(node.left)
                right = eval_node(node.right)
                return allowed_ops[type(node.op)](left, right)
            if isinstance(node, ast.UnaryOp):
                return allowed_ops[type(node.op)](eval_node(node.operand))
            raise ValueError("Unsupported expression")

        tree = ast.parse(expression, mode="eval")
        return eval_node(tree.body)


agent = Agent(
    Model("gpt-5.4-mini"),
    tools=[Calculator()],
    instructions="Use the calculator tool when needed. Be concise and give the final answer.",
    stop_when=[step_count(6)],
)

result = agent.run("What is 17 * 23?")

print(result.output)
print(result.stopped_by)

