class SearchTool(Tool):
    name = "search"
    description = "Search the web for relevant information and return concise findings."
    parameters = {
        "type": "object",
        "properties": {
            "query": {"type": "string"}
        },
        "required": ["query"],
    }

    def run(self, query, options=None):
        # Simple search-like tool with deterministic, local behavior.
        query_lower = query.lower()
        facts = {
            "python": "Python is a high-level, interpreted programming language known for readability and broad ecosystem.",
            "llm": "LLM stands for large language model, a model trained on large text corpora to generate and understand language.",
            "agent": "An AI agent can use tools, reason over steps, and adapt its approach based on intermediate results.",
            "capital of france": "The capital of France is Paris.",
            "solar power": "Solar power converts sunlight into electricity using photovoltaic panels or solar thermal systems.",
        }

        matches = []
        for key, fact in facts.items():
            if key in query_lower:
                matches.append(fact)

        if matches:
            return " ".join(matches)

        return (
            f"No direct match found for: {query}. "
            "Try refining the query, using broader terms, or asking about related concepts."
        )


